<template><div><div class="page-title"><div><h1>规则与特殊日期</h1><p>设置连续工作上限、夜班限制与节假日计班系数。</p></div></div><el-row :gutter="18"><el-col :span="12"><el-card><template #header>科室排班规则</template><el-form label-width="150px"><el-form-item label="连续工作天数上限"><el-input-number v-model="rule.max_consecutive_days" :min="1" :max="14"/></el-form-item><el-form-item label="周末轮循"><el-switch v-model="rule.weekend_rotation"/></el-form-item><el-form-item label="节假日优先级"><el-switch v-model="rule.holiday_priority"/></el-form-item><el-form-item label="夜班后禁排白班"><el-switch v-model="rule.forbid_night_to_day"/></el-form-item><el-button type="primary" @click="save">保存规则</el-button></el-form></el-card></el-col><el-col :span="12"><el-card><template #header>法定节假日与特殊工作日</template><el-form inline><el-form-item><el-date-picker v-model="holiday.date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item><el-input v-model="holiday.name" placeholder="名称"/></el-form-item><el-form-item><el-input-number v-model="holiday.multiplier" :min="1" :max="3" :step="0.5"/></el-form-item><el-button @click="addHoliday">新增</el-button></el-form><el-table :data="holidays"><el-table-column label="日期"><template #default="scope">{{scope.row.date.slice(0,10)}}</template></el-table-column><el-table-column prop="name" label="名称"/><el-table-column prop="multiplier" label="计班系数"/></el-table></el-card></el-col></el-row></div></template>
<script setup lang="ts">
import {onMounted, reactive, ref} from 'vue'; import {ElMessage} from 'element-plus'; import api from '../api/http'
const rule=reactive({department_id:1,max_consecutive_days:5,weekend_rotation:true,holiday_priority:true,forbid_night_to_day:true}), holiday=reactive({date:new Date().toISOString().slice(0,10),name:'',is_workday:false,multiplier:2}), holidays=ref<any[]>([])
async function load(){Object.assign(rule,await api.get('/schedule-rules',{params:{department_id:1}}));holidays.value=await api.get('/holidays')};async function save(){try{await api.put('/schedule-rules',rule);ElMessage.success('规则已保存')}catch(error:any){ElMessage.error(error.message)}};async function addHoliday(){try{await api.post('/holidays',holiday);ElMessage.success('特殊日期已保存');await load()}catch(error:any){ElMessage.error(error.message)}};onMounted(load)
</script>